If you want to create a 3D cylinder in a programming environment, you can use libraries like Three.js for JavaScript, or you can use a 3D modeling software like Blender. If you want to do it in a programming language, you can use a library like OpenGL or WebGL. 

Below is an example of how you might create a 3D cylinder in Three.js:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>3D Cylinder with Three.js</title>
  <style>
    body { margin: 0; }
    canvas { display: block; }
  </style>
</head>
<body>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
  <script>
    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xeeeeee);

    // Camera
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 5;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Cylinder geometry
    const radiusTop = 1;
    const radiusBottom = 1;
    const height = 2;
    const radialSegments = 32;
    const heightSegments = 1;
    const openEnded = false;
    const geometry = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, radialSegments, heightSegments, openEnded);

    // Material
    const material = new THREE.MeshStandardMaterial({ color: 0x0077ff });

    // Mesh
    const cylinder = new THREE.Mesh(geometry, material);
    scene.add(cylinder);

    // Light
    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);
      cylinder.rotation.x += 0.01;
      cylinder.rotation.y += 0.01;
      renderer.render(scene, camera);
    }
    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
